  "inlineSchema": "// Prisma schema for EcoCircuit Smart E-Waste Management Platform\n// Target Database: PostgreSQL\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// -----------------------------------------------------------------------------\n// ENUMS\n// -----------------------------------------------------------------------------\n\nenum UserRole {\n  CITIZEN\n  COLLECTOR\n  ADMIN\n}\n\nenum VerificationStatus {\n  PENDING\n  VERIFIED\n  REJECTED\n}\n\nenum PickupStatus {\n  PENDING\n  ASSIGNED\n  ACCEPTED\n  COLLECTED\n  DELIVERED_TO_RECYCLER\n  COMPLETED\n  CANCELLED\n  FAILED\n}\n\n// -----------------------------------------------------------------------------\n// MODELS\n// -----------------------------------------------------------------------------\n\nmodel User {\n  id        String   @id @default(uuid())\n  name      String   @db.VarChar(120)\n  email     String   @unique @db.VarChar(255)\n  phone     String   @db.VarChar(30)\n  role      UserRole @default(CITIZEN)\n  createdAt DateTime @default(now()) @db.Timestamptz\n  updatedAt DateTime @updatedAt @db.Timestamptz\n\n  // Relations\n  collectorProfile CollectorProfile?\n  citizenPickups   PickupRequest[]       @relation(\"CitizenPickups\")\n  assignedPickups  PickupRequest[]       @relation(\"CollectorPickups\")\n  statusHistory    PickupStatusHistory[]\n\n  @@index([email])\n  @@index([role])\n}\n\nmodel CollectorProfile {\n  id                 String             @id @default(uuid())\n  userId             String             @unique\n  businessName       String             @db.VarChar(180)\n  contactInfo        String             @db.VarChar(255)\n  verificationStatus VerificationStatus @default(PENDING)\n  serviceAreas       String[] // Array of covered localities or pincodes\n  createdAt          DateTime           @default(now()) @db.Timestamptz\n  updatedAt          DateTime           @updatedAt @db.Timestamptz\n\n  // Relations\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([verificationStatus])\n}\n\nmodel WasteCategory {\n  id                   String   @id @default(uuid())\n  name                 String   @unique @db.VarChar(100)\n  description          String   @db.Text\n  disposalInstructions String   @db.Text\n  createdAt            DateTime @default(now()) @db.Timestamptz\n  updatedAt            DateTime @updatedAt @db.Timestamptz\n\n  // Relations\n  items PickupItem[]\n}\n\nmodel PickupRequest {\n  id                String       @id @default(uuid())\n  citizenId         String\n  collectorId       String?\n  pickupAddress     String       @db.VarChar(255)\n  locality          String       @db.VarChar(120)\n  pincode           String       @db.VarChar(20)\n  preferredDate     DateTime     @db.Date\n  preferredTimeSlot String       @db.VarChar(60) // \"Morning (08:00 AM - 12:00 PM)\", etc.\n  currentStatus     PickupStatus @default(PENDING)\n  createdAt         DateTime     @default(now()) @db.Timestamptz\n  updatedAt         DateTime     @updatedAt @db.Timestamptz\n\n  // Relations\n  citizen       User                  @relation(\"CitizenPickups\", fields: [citizenId], references: [id], onDelete: Restrict)\n  collector     User?                 @relation(\"CollectorPickups\", fields: [collectorId], references: [id], onDelete: SetNull)\n  items         PickupItem[]\n  statusHistory PickupStatusHistory[]\n\n  @@index([currentStatus])\n  @@index([citizenId])\n  @@index([collectorId])\n  @@index([pincode])\n}\n\nmodel PickupItem {\n  id              String   @id @default(uuid())\n  pickupRequestId String\n  wasteCategoryId String\n  quantity        Int      @default(1)\n  estimatedWeight Float // in kilograms\n  description     String?  @db.VarChar(255)\n  createdAt       DateTime @default(now()) @db.Timestamptz\n\n  // Relations\n  pickupRequest PickupRequest @relation(fields: [pickupRequestId], references: [id], onDelete: Cascade)\n  category      WasteCategory @relation(fields: [wasteCategoryId], references: [id], onDelete: Restrict)\n\n  @@index([pickupRequestId])\n}\n\nmodel CollectionCentre {\n  id                      String             @id @default(uuid())\n  name                    String             @db.VarChar(150)\n  address                 String             @db.VarChar(255)\n  latitude                Float\n  longitude               Float\n  contactDetails          String             @db.VarChar(120)\n  acceptedWasteCategories String[] // List of category names or IDs\n  verificationStatus      VerificationStatus @default(VERIFIED)\n  createdAt               DateTime           @default(now()) @db.Timestamptz\n  updatedAt               DateTime           @updatedAt @db.Timestamptz\n\n  @@index([verificationStatus])\n}\n\nmodel PickupStatusHistory {\n  id              String        @id @default(uuid())\n  pickupRequestId String\n  previousStatus  PickupStatus?\n  newStatus       PickupStatus\n  changedBy       String // User ID of citizen, collector, or admin making the change\n  reason          String?       @db.VarChar(255)\n  timestamp       DateTime      @default(now()) @db.Timestamptz\n\n  // Relations\n  pickupRequest PickupRequest @relation(fields: [pickupRequestId], references: [id], onDelete: Cascade)\n  actor         User          @relation(fields: [changedBy], references: [id], onDelete: Restrict)\n\n  @@index([pickupRequestId])\n  @@index([timestamp])\n}\n",
